/** Preset ids — mirrors the backend `ColorTheme` enum; the merchant picks one in the seller console. */
export enum ColorTheme {
    LIGHT = "LIGHT",
    DARK = "DARK",
    NATURE = "NATURE",
    OCEAN = "OCEAN",
    MIDNIGHT = "MIDNIGHT",
    FOREST_WHISPER = "FOREST_WHISPER",
    DESERT_MIRAGE = "DESERT_MIRAGE",
    MIDNIGHT_DUSK = "MIDNIGHT_DUSK",
    ROSE = "ROSE",
    LAVENDER = "LAVENDER",
    AURORA_LIGHTS = "AURORA_LIGHTS",
    CYBERPUNK = "CYBERPUNK",
    AUTUMN_HARVEST = "AUTUMN_HARVEST",
    CYBER_NEON = "CYBER_NEON",
    SUNSET = "SUNSET",
    FOREST = "FOREST",
    DESERT = "DESERT",
    SKY = "SKY",
    EARTH = "EARTH",
    FIRE = "FIRE",
    ICE = "ICE",
    BLOSSOM = "BLOSSOM",
    GOLDEN = "GOLDEN",
    GRAPE = "GRAPE",
    PEACH = "PEACH",
    MINT = "MINT",
    SAND = "SAND",
    RAINBOW = "RAINBOW",
    NEON = "NEON",
    PASTEL = "PASTEL",
}

const colorThemeData: Record<ColorTheme, ColorSchema> = {
    [ColorTheme.LIGHT]: LIGHT_COLOR_SCHEMA,
    [ColorTheme.DARK]: DARK_COLOR_SCHEMA,
    [ColorTheme.NATURE]: NATURE_COLOR_SCHEMA,
    [ColorTheme.OCEAN]: OCEAN_COLOR_SCHEMA,
    [ColorTheme.MIDNIGHT]: MIDNIGHT_COLOR_SCHEMA,
    [ColorTheme.FOREST_WHISPER]: FOREST_WHISPER_COLOR_SCHEMA,
    [ColorTheme.DESERT_MIRAGE]: DESERT_MIRAGE_COLOR_SCHEMA,
    [ColorTheme.MIDNIGHT_DUSK]: MIDNIGHT_DUSK_COLOR_SCHEMA,
    [ColorTheme.ROSE]: ROSE_COLOR_SCHEMA,
    [ColorTheme.LAVENDER]: LAVENDER_COLOR_SCHEMA,
    [ColorTheme.AURORA_LIGHTS]: AURORA_LIGHTS_COLOR_SCHEMA,
    [ColorTheme.CYBERPUNK]: CYBERPUNK_COLOR_SCHEMA,
    [ColorTheme.AUTUMN_HARVEST]: AUTUMN_HARVEST_COLOR_SCHEMA,
    [ColorTheme.CYBER_NEON]: CYBER_NEON_COLOR_SCHEMA,
    [ColorTheme.SUNSET]: SUNSET_COLOR_SCHEMA,
    [ColorTheme.FOREST]: FOREST_COLOR_SCHEMA,
    [ColorTheme.DESERT]: DESERT_COLOR_SCHEMA,
    [ColorTheme.SKY]: SKY_COLOR_SCHEMA,
    [ColorTheme.EARTH]: EARTH_COLOR_SCHEMA,
    [ColorTheme.FIRE]: FIRE_COLOR_SCHEMA,
    [ColorTheme.ICE]: ICE_COLOR_SCHEMA,
    [ColorTheme.BLOSSOM]: BLOSSOM_COLOR_SCHEMA,
    [ColorTheme.GOLDEN]: GOLDEN_COLOR_SCHEMA,
    [ColorTheme.GRAPE]: GRAPE_COLOR_SCHEMA,
    [ColorTheme.PEACH]: PEACH_COLOR_SCHEMA,
    [ColorTheme.MINT]: MINT_COLOR_SCHEMA,
    [ColorTheme.SAND]: SAND_COLOR_SCHEMA,
    [ColorTheme.RAINBOW]: RAINBOW_COLOR_SCHEMA,
    [ColorTheme.NEON]: NEON_COLOR_SCHEMA,
    [ColorTheme.PASTEL]: PASTEL_COLOR_SCHEMA,
};

/**
 * Retrieves the ColorSchema data for a given ColorTheme.
 * @param theme The ColorTheme enum member.
 * @returns The corresponding ColorSchema object (LIGHT for an unknown value).
 */
export function getThemeColors(theme: ColorTheme): ColorSchema {
    const colors = colorThemeData[theme];
    return colors ? colors : colorThemeData[ColorTheme.LIGHT];
}
